DROP VIEW IF EXISTS `Alphabetical list of products`;
CREATE VIEW `Alphabetical list of products` AS
select `northwind`.`Products`.`CategoryID` AS `CategoryID`,`northwind`.`Products`.`Discontinued` AS `Discontinued`,`northwind`.`Products`.`ProductID` AS `ProductID`,`northwind`.`Products`.`ProductName` AS `ProductName`,`northwind`.`Products`.`QuantityPerUnit` AS `QuantityPerUnit`,`northwind`.`Products`.`ReorderLevel` AS `ReorderLevel`,`northwind`.`Products`.`SupplierID` AS `SupplierID`,`northwind`.`Products`.`UnitPrice` AS `UnitPrice`,`northwind`.`Products`.`UnitsInStock` AS `UnitsInStock`,`northwind`.`Products`.`UnitsOnOrder` AS `UnitsOnOrder`,`northwind`.`Categories`.`CategoryName` AS `CategoryName` from (`northwind`.`Categories` join `northwind`.`Products` on((`northwind`.`Categories`.`CategoryID` = `northwind`.`Products`.`CategoryID`))) where (`northwind`.`Products`.`Discontinued` = 0)